    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1ui4y1f7lg', 'course-bili-bv1ui4y1f7lg', '100001', '0', 'BILI-PM-001', 'course-category-product', 'instructor-bili-1827450921', '产品经理零基础入门（二）需求分析课程（全35集）', '35 讲完整课程 · 9 小时 19 分钟', '本套视频课程共35集，给想进入互联网行业、零基础入门产品经理的小伙伴，深度讲解产品经理最重要的能力之一：需求分析。尤其对于初中级产品经理而言，需求分析是必须具备的能力。作为产品经理，每天要接触到大大小小不同的需求，', '课程简介：本套视频课程共35集，给想进入互联网行业、零基础入门产品经理的小伙伴，深度讲解产品经理最重要的能力之一：需求分析。尤其对于初中级产品经理而言，需求分析是必须具备的能力。作为产品经理，每天要接触到大大小小不同的需求，在面对需求时，就要进行有效的需求分析，才能更好地了解问题，最终制定合理的解决方案。课程结构：共 5 章 35 讲，累计时长 9 小时 19 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/7dc9d380cdf2e33c9da3c0343a5c994173fa7350.png', '["产品经理","需求分析","项目实战","产品经理零基础入门","需求分析课程","全35集"]', 33560, 35, 48677, '4.3', 11199, 'BV1Ui4y1f7LG', NULL, NULL, NULL, 1, 0, 'standard', NULL, '黑马产品经理', 0, 'tenant', 'published', '2022-02-16T10:18:17.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
