    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1r24y1k76d', 'course-bili-bv1r24y1k76d', '100001', '0', 'BILI-PM-004', 'course-category-product', 'instructor-bili-606305397', '零基础学习B端交互体验UI设计-从理论到原型到实战到作品集', '21 讲完整课程 · 10 小时 54 分钟', '这是一套面向希望零基础学习B端设计的保姆级教程，让你从零到一能够实现并制作设计界面。课程从交互体验理论基础，到交互原型设计及交互文档标注，以及B端的Ui设计规范和原子组件库建立并能够输出对接开发和做作品集排', '课程简介：嗨，这是一套面向希望零基础学习B端设计的保姆级教程，让你从零到一能够实现并制作设计界面。课程从交互体验理论基础，到交互原型设计及交互文档标注，以及B端的Ui设计规范和原子组件库建立并能够输出对接开发和做作品集排版。ToB端的蓝海行业，让这套教程成为你步入B端的第一个陪伴者。课程结构：共 3 章 21 讲，累计时长 10 小时 54 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/0dc6e4f61f0e28aa1d543e080da48fdd3600aa10.png', '["产品经理","需求分析","项目实战","B端教程"]', 39243, 21, 14329, '4.4', 4260, 'BV1r24y1k76d', '79.00', '126.40', 'CNY', 0, 0, 'standard', NULL, '设计师的睡前毒物', 0, 'tenant', 'published', '2022-12-05T04:31:56.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
