VALUES
    ('course-bili-bv1ky411g7x2', 'course-bili-bv1ky411g7x2', '100001', '0', 'BILI-PM-005', 'course-category-product', 'instructor-bili-1827450921', '产品经理零基础入门（五）产品需求文档PRD（全16集）', '16 讲完整课程 · 3 小时 53 分钟', '产品需求文档（PRD）是对产品需求以实际可落地方式进行细化描述的文档。最主要的目的是让产品团队、公司管理层、客户以及其他相关部门对产品的认知和预期达成一致。撰写需求文档作为产品经理的基本功，其重要性不言而喻，本套视频将教', '课程简介：产品需求文档（PRD）是对产品需求以实际可落地方式进行细化描述的文档。最主要的目的是让产品团队、公司管理层、客户以及其他相关部门对产品的认知和预期达成一致。撰写需求文档作为产品经理的基本功，其重要性不言而喻，本套视频将教会大家写出、并写好产品需求文档PRD，属产品经理入门和进阶必备。课程结构：共 2 章 16 讲，累计时长 3 小时 53 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/24eb34b000f9216a4f0f3b3fd25b2e178df7a349.png', '["产品经理","需求分析","项目实战","产品经理零基础入门","产品需求文档PRD","全16集"]', 13983, 16, 43264, '4.3', 11841, 'BV1kY411G7x2', NULL, NULL, NULL, 1, 0, 'standard', NULL, '黑马产品经理', 0, 'tenant', 'published', '2022-03-03T08:29:32.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
