    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1ie411x7gs', 'course-bili-bv1ie411x7gs', '100001', '0', 'BILI-PM-012', 'course-category-product', 'instructor-bili-37974444', '黑马程序员产品经理基础课程-4天Axure入门到精通-产品原型设计', '41 讲完整课程 · 9 小时 47 分钟', 'Axure作为产品经理必备的技能，就像是士兵的枪一样；Axure的运用是否熟练，能否高效产出各类原型，也决定了产品经理在团队中的地位和发展，Axure从入门到精通，让初级产品经理顺利度过职场的前中期。', '课程简介：Axure作为产品经理必备的技能，就像是士兵的枪一样；Axure的运用是否熟练，能否高效产出各类原型，也决定了产品经理在团队中的地位和发展，Axure从入门到精通，让初级产品经理顺利度过职场的前中期。课程结构：共 6 章 41 讲，累计时长 9 小时 47 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/31fc0f374476e2953c4310704ddd71dabb99f097.jpg', '["产品经理","需求分析","项目实战","4天Axure入门到精通","产品原型设计"]', 35240, 41, 83117, '4.4', 19264, 'BV1iE411x7gS', NULL, NULL, NULL, 1, 0, 'standard', NULL, '黑马程序员', 0, 'tenant', 'published', '2020-03-05T03:54:18.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
