INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1hp4y1r7yy', 'course-bili-bv1hp4y1r7yy', '100001', '0', 'BILI-PM-016', 'course-category-product', 'instructor-bili-479659041', '产品经理实战项目系列教程', '114 讲完整课程 · 58 小时 23 分钟', '本套课程从零基础讲解产品经理课体系，从互联网思维—产品思维—需求分析—前后端业务梳理；本套体系和市面上产品课程的最大区别有以下3点：1、只讲你能听懂的产品方法论；2、以产品思维为核心的项目实战体系；3、带你梳理前后', '课程简介：本套课程从零基础讲解产品经理课体系，从互联网思维—产品思维—需求分析—前后端业务梳理；本套体系和市面上产品课程的最大区别有以下3点：1、只讲你能听懂的产品方法论；2、以产品思维为核心的项目实战体系；3、带你梳理前后端的业务逻辑；帮你打破听不懂—想不到—屡不清—做不明白的产品诅咒；本套课程是基础的产品思维培养课程，仅涉及到一小部分实战项目；课程结构：共 15 章 114 讲，累计时长 58 小时 23 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'intermediate', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/997d21296140ba41a54fb85ba1531a295ab94bc4.jpg', '["产品经理","需求分析","项目实战","产品经理实战项目系列教程"]', 210227, 114, 98601, '4.3', 25794, 'BV1Hp4y1r7YY', NULL, NULL, NULL, 1, 0, 'standard', NULL, '懂设计的产品人', 0, 'tenant', 'published', '2020-11-21T15:36:08.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
