    ('course-bili-bv1nz4y1t7xx', 'course-bili-bv1nz4y1t7xx', '100001', '0', 'BILI-PM-017', 'course-category-product', 'instructor-bili-3546377825028384', 'CRM产品|SaaS产品|ToB产品|教务管理系统|产品经理', '24 讲完整课程 · 3 小时 32 分钟', 'CRM产品|SaaS产品|ToB产品|教务管理系统|产品经理。共 24 讲，累计 3.5 小时，由 职场圈 讲解，章节结构完整，可直接在课程播放器中观看。', '课程简介：全网高赞的教务管理系统项目，累计时长 3 小时 32 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'intermediate', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/f19057ee86aaaacc1d22e4fa04cc87ca7dc82ca0.png', '["产品经理","需求分析","项目实战","B端产品经理","CRM产品","SaaS产品"]', 12756, 24, 2602, '4.4', 881, 'BV1Nz4y1T7xX', NULL, NULL, NULL, 1, 0, 'standard', NULL, '职场圈', 0, 'tenant', 'published', '2023-09-02T04:30:12.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
