VALUES
    ('course-bili-bv1he411g7mu', 'course-bili-bv1he411g7mu', '100001', '0', 'BILI-PM-022', 'course-category-product', 'instructor-bili-415938397', '首发 | 产品经理入门到精通（48集附全套资料）', '48 讲完整课程 · 1 小时 59 分钟', '黑马程序员深圳中心 发布的《首发 | 产品经理入门到精通（48集附全套资料）》，共 48 讲，总时长 1 小时 59 分钟。', '课程简介：《首发 | 产品经理入门到精通（48集附全套资料）》由 黑马程序员深圳中心 发布，完整收录 48 讲内容。课程结构：共 6 章 48 讲，累计时长 1 小时 59 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/29ef34c6aca14e0153f63dc39b554263f22ffbec.jpg', '["产品经理","需求分析","项目实战","首发","产品经理入门到精通","48集附全套资料"]', 7171, 48, 34608, '4.4', 11524, 'BV1hE411G7mU', NULL, NULL, NULL, 1, 0, 'standard', NULL, '黑马程序员深圳中心', 0, 'tenant', 'published', '2020-03-15T09:08:06.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
