VALUES
    ('course-bili-season-401110', 'course-bili-season-401110', '100001', '0', 'BILI-PM-024', 'course-category-product', 'instructor-bili-350964713', 'Axure9零基础入门到精通教程', '44 讲完整课程 · 4 小时 2 分钟', '艾斯的Axure峡谷 发布的《Axure9零基础入门到精通教程》，共 44 讲，总时长 4 小时 2 分钟。', '课程简介：《Axure9零基础入门到精通教程》由 艾斯的Axure峡谷 发布，完整收录 44 讲内容。课程结构：共 1 章 44 讲，累计时长 4 小时 2 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/cdf94615dee45f747ea10037aacaa4b25f13c7b3.jpg', '["产品经理","需求分析","项目实战"]', 14531, 44, 804, '4.4', 70, 'BV1wt4y1P7Jw', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '艾斯的Axure峡谷', 0, 'tenant', 'published', '2022-09-20T15:15:58.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
