VALUES
    ('course-bili-bv1hz4y1a7gg', 'course-bili-bv1hz4y1a7gg', '100001', '0', 'BILI-PM-027', 'course-category-product', 'instructor-bili-396491181', '2022新版产品经理入门到精通，产品经理认知、流程、结构和原型设计等全套教程', '91 讲完整课程 · 25 小时 25 分钟', '在一个团队中，不同的角色要明确自己该做的事，自己的重点，而在产品经理这个角色中，一样要理解自己是谁，自己在这个团队中应起的作用是什么？本视频可以让你能够基于需求完成产品对应的流程、结构和原型设计。', '课程简介：在一个团队中，不同的角色要明确自己该做的事，自己的重点，而在产品经理这个角色中，一样要理解自己是谁，自己在这个团队中应起的作用是什么？本视频可以让你能够基于需求完成产品对应的流程、结构和原型设计。课程结构：共 12 章 91 讲，累计时长 25 小时 25 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/c74aefddcea5301b11e5d852894b49bae005f253.jpg', '["产品经理","需求分析","项目实战","产品经理认知","流程","结构和原型设计等全套教程"]', 91526, 91, 5440, '4.3', 978, 'BV1hZ4y1A7GG', NULL, NULL, NULL, 1, 0, 'standard', NULL, '传智AI', 0, 'tenant', 'published', '2021-02-24T08:30:31.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
