    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1nv411e7zd', 'course-bili-bv1nv411e7zd', '100001', '0', 'BILI-PM-028', 'course-category-product', 'instructor-bili-37974444', '黑马程序员_产品经理快速入门，如何才能成为一名产品经理的教程', '63 讲完整课程 · 14 小时 17 分钟', '课程特色：课程总共分为5章 第一章，认知产品经理；让你对产品经理这个工作是做什么的，不再有误解；产品经理的主要工作内容，不再是管中窥豹，而是全面了解产品经理每天在做什么；产品经理必懂的项目管理和软件，', '课程简介：课程特色：课程总共分为5章 第一章，认知产品经理；让你对产品经理这个工作是做什么的，不再有误解；产品经理的主要工作内容，不再是管中窥豹，而是全面了解产品经理每天在做什么；产品经理必懂的项目管理和软件，开始要学习技能了，一定要好好掌握才可以；产品经理必会的各类文档、会议和原型，各种典型文档、需要参加的会议、制作的原型，产品经理的就业，大家最关心的问题来了，未来的就业方向和思路的选择，来深入了解一下吧！课程结构：共 8 章 63 讲，累计时长 14 小时 17 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/0b4b8e2ecff62df27b8c24ac1d3bef84e3fc638d.jpg', '["产品经理","需求分析","项目实战","产品经理快速入门"]', 51436, 63, 21453, '4.4', 5296, 'BV1nv411e7zd', NULL, NULL, NULL, 1, 0, 'standard', NULL, '黑马程序员', 0, 'tenant', 'published', '2021-01-29T10:58:10.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
