    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-2149881', 'course-bili-season-2149881', '100001', '0', 'BILI-PM-029', 'course-category-product', 'instructor-bili-1391967442', 'Axure快速入门', '32 讲完整课程 · 3 小时 2 分钟', '市面上的终端设备千千万，实际的原型设计中，就需要我们针对适配的终端设备，自定义相应的设备尺寸。Axure原型设计中，支持自定义设备尺寸进行对应的原型设计。', '课程简介：市面上的终端设备千千万，实际的原型设计中，就需要我们针对适配的终端设备，自定义相应的设备尺寸。Axure原型设计中，支持自定义设备尺寸进行对应的原型设计。课程结构：共 1 章 32 讲，累计时长 3 小时 2 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/730619defc87848c4ae436f2e5bd9ad81f9c446b.jpg', '["产品经理","需求分析","项目实战","Axure快速入门"]', 10974, 32, 547, '4.3', 10, 'BV1GX4y127db', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '岳小哥AI', 0, 'tenant', 'published', '2023-05-04T13:50:34.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
