INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-35060', 'course-bili-season-35060', '100001', '0', 'BILI-PM-030', 'course-category-product', 'instructor-bili-2555148', '经管 《人人都是产品经理》：一本书讲清楚如何入门产品经理', '31 讲完整课程 · 2 小时 33 分钟', '1、产品经理的基础能力 其一，是从“用产品”的思维转变为“做产品”的思维，要能够透过现象看本质，透过产品的功能琢磨产品背后的规则、逻辑和长远规划。', '1、产品经理的基础能力 其一，是从“用产品”的思维转变为“做产品”的思维，要能够透过现象看本质，透过产品的功能琢磨产品背后的规则、逻辑和长远规划。是要能够有效地管理资源，也就是有效地管理好信息、时间、人和钱。2.、看视频 二、看视频 课程结构：共 1 章 31 讲，累计时长 2 小时 33 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/56f21cb76ff4d345b9e70e379364920afa019f41.jpg', '["产品经理","需求分析","项目实战","经管","人人都是产品经理"]', 9204, 31, 4783, '4.4', 580, 'BV1ia4y1Y7sv', NULL, NULL, NULL, 1, 0, 'standard', NULL, '红翻车che', 0, 'tenant', 'published', '2020-06-18T13:20:49.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
