    ('course-bili-season-999472', 'course-bili-season-999472', '100001', '0', 'BILI-PM-031', 'course-category-product', 'instructor-bili-522976477', '产品经理实战经验', '47 讲完整课程 · 5 小时 22 分钟', '用最简单的话告诉你产品经理的思维体系，下期会更新产品经理的日常工作内容及如何去做这些基础工作', '课程简介：干货预警！用最简单的话告诉你产品经理的思维体系，下期会更新产品经理的日常工作内容及如何去做这些基础工作 课程结构：共 1 章 47 讲，累计时长 5 小时 22 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/e852b5f1ee4a40c7dce0cb4135f58dca1a1ca5d0.jpg', '["产品经理","需求分析","项目实战","产品经理实战经验"]', 19373, 47, 10136, '4.4', 2892, 'BV1PG4y1j73R', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'Eden说产品', 0, 'tenant', 'published', '2023-01-08T13:13:19.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
