VALUES
    ('course-bili-bv12fyt6ge1p', 'course-bili-bv12fyt6ge1p', '100001', '0', 'BILI-PM-032', 'course-category-product', 'instructor-bili-1214605578', 'NPDP产品经理认证考试必看精讲课程！第三版零基础系统教程||核心考点||配套资料||一次通关上岸！', '95 讲完整课程 · 22 小时 51 分钟', '【NPDP产品经理认证考试新版精讲课程（第三版）零基础系统教程】，建议【先收藏再观看】。【NPDP新版模拟题、学习计划、思维导图、知识点集锦等学习资料大礼包】，需要的同学，留言“获取”即可~~ 如果视频对你有帮助的话，', '课程简介：【NPDP产品经理认证考试新版精讲课程（第三版）零基础系统教程】，建议【先收藏再观看】。【NPDP新版模拟题、学习计划、思维导图、知识点集锦等学习资料大礼包】，需要的同学，留言“获取”即可~~ 如果视频对你有帮助的话，可以三连支持一下up哦，点个赞也行，预祝大家考试顺利~~ 课程结构：共 12 章 95 讲，累计时长 22 小时 51 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/71de8d9649b2f3aa1bf39c4237fbf43411ca56dc.jpg', '["产品经理","需求分析","项目实战","核心考点","配套资料","一次通关上岸！"]', 82301, 95, 377, '4.3', 43, 'BV12fYt6GE1p', NULL, NULL, NULL, 1, 0, 'standard', NULL, '希赛NPDP产品经理', 0, 'tenant', 'published', '2026-09-10T06:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
