    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1kv4y1w7sq', 'course-bili-bv1kv4y1w7sq', '100001', '0', 'BILI-PM-033', 'course-category-product', 'instructor-bili-1827450921', '2023最新产品经理入门基础课程视频（全48集）', '48 讲完整课程 · 6 小时 29 分钟', '本套产品经理零基础入门课程，主要分为六大部分：1、认识产品经理；2、问题思考维度；3、产品解决方案；4、项目立项；5、思维导图-Xmind快速入门；6、原型设计-墨刀。全套共48集，包含从产品岗位、行业，到产品经理流程、', '课程简介：本套产品经理零基础入门课程，主要分为六大部分：1、认识产品经理；2、问题思考维度；3、产品解决方案；4、项目立项；5、思维导图-Xmind快速入门；6、原型设计-墨刀。全套共48集，包含从产品岗位、行业，到产品经理流程、到产品工具，非常适合产品经理零基础小白入门。课程结构：共 6 章 48 讲，累计时长 6 小时 29 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/be6ce61c383f35ce718cfd5143ef724da65d21ea.png', '["产品经理","需求分析","项目实战","B站首发","全48集"]', 23379, 48, 210785, '4.4', 51592, 'BV1kv4y1W7SQ', NULL, NULL, NULL, 1, 0, 'standard', NULL, '黑马产品经理', 0, 'tenant', 'published', '2023-02-17T11:09:11.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
