VALUES
    ('course-bili-season-1004382', 'course-bili-season-1004382', '100001', '0', 'BILI-PM-034', 'course-category-product', 'instructor-bili-569427944', 'PRD框架V2.1-使用教程', '13 讲完整课程 · 2 小时 36 分钟', 'PRD框架V2.1-使用教程。共 13 讲，累计 2.6 小时，由 产品教练 讲解，章节结构完整，可直接在课程播放器中观看。', '课程简介：墨刀版框架系列教程，累计时长 2 小时 36 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/873eec63234ba8fe5c062f799efdf9c883f75065.jpg', '["产品经理","需求分析","项目实战","PRD框架V2.1","使用教程"]', 9395, 13, 401, '4.2', 5, 'BV1G14y1w7bQ', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '产品教练', 0, 'tenant', 'published', '2022-12-28T09:01:47.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
