VALUES
    ('course-bili-season-93258', 'course-bili-season-93258', '100001', '0', 'BILI-PM-036', 'course-category-product', 'instructor-bili-4217008', 'Axure 教程汇总', '42 讲完整课程 · 3 小时 57 分钟', '芝士酵坊 发布的《Axure 教程汇总》，共 42 讲，总时长 3 小时 57 分钟。', '课程简介：《Axure 教程汇总》由 芝士酵坊 发布，完整收录 42 讲内容。课程结构：共 5 章 42 讲，累计时长 3 小时 57 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/28587028737f3fafc17128c709116f43a5120758.jpg', '["产品经理","需求分析","项目实战","Axure","教程汇总"]', 14274, 42, 24396, '4.3', 2073, 'BV1bG4y1f7yY', NULL, NULL, NULL, 1, 0, 'standard', NULL, '芝士酵坊', 0, 'tenant', 'published', '2022-11-11T08:35:46.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
